# -*- coding: utf-8 -*-
"""Itinerari popolari per destinazione (codice IATA), pensati per 10-12 giorni ad agosto (9-11 notti a terra).
Costi: stima a terra per persona, mid-range, intero giro, volo internazionale escluso.
T(nome, stili, ritmo, tappe "Luogo notti|Luogo notti", come ci si muove, costo pp, highlight, nota agosto, open-jaw)
"""

PACES = ("rilassato", "medio", "intenso")


def T(name, styles, pace, stops, move, cost, hl, aug, oj=None):
    t = []
    for s in stops.split("|"):
        place, n = s.rsplit(" ", 1)
        t.append([place.strip(), int(n)])
    tot = sum(n for _, n in t)
    assert 9 <= tot <= 11, (name, tot)
    assert pace in PACES, (name, pace)
    assert 2 <= len(hl) <= 3, name
    return {"n": name, "s": styles, "r": pace, "t": t, "m": move, "c": cost, "h": hl, "a": aug, "oj": oj, "src": []}


